select * from dws_xc_transfer_day_d
where is_delete = 0

     and report_date >= #{reportDateStart}


     and report_date <= #{reportDateEnd}

order by report_date desc;

select * from dws_xc_transfer_day_call_d
where is_delete = 0

     and report_date >= #{reportDateStart}


     and report_date <= #{reportDateEnd}

order by report_date desc;

select dataPacket,sum(lock_num) as lockNum from dws_xc_collding_distrubute_day_d
where  report_date >= #{reportDateStart} and report_date <= #{reportDateEnd} 
group by dataPacket order by dataPacket;

select * from dws_xc_data_ratio_d where
   report_date >= #{reportDateStart} 
order by report_date desc
